import assert from 'node:assert/strict';
import {chromium} from 'playwright';
import {spawn} from 'node:child_process';
import {mkdir,readFile,writeFile} from 'node:fs/promises';

// SHOP03a integration contract, using observed synthetic states. Monetary and
// revision oracles below are literal; no expected result is generated by H2.
// Browser persistence tests are not gameplay observations or strategy validation.
const key='balatro-advisor.confirmed.v1',port='4197',origin='http://127.0.0.1:'+port;
const dir='docs/evidencia/shop-session';await mkdir(dir,{recursive:true});
const base=JSON.parse(await readFile('examples/shop-purchase.json','utf8'));
const known=value=>({status:'known',source:'manual',value});
const joker=(id='owned-joker')=>({instanceId:id,catalogId:'joker',edition:known('base'),stickers:known([]),sellValue:known(1),counters:{}});
function fixture({money=25,jokers=[]}={}){
 const state=structuredClone(base);state.runId='synthetic-shop-session';state.observed.money=known(money);state.observed.jokers=known(jokers);
 state.observed.shop=known({shopId:'shop-session',cardOffers:[],ignoredOtherOffers:[]});
 // Existing hypothetical inputs must never become real cards, money or income.
 state.assumptions.probes=[];state.assumptions.roundPlans=[];return state;
}
const report={date:new Date().toISOString(),environment:'Chrome temporary profiles; desktop/mobile emulation',gameObservation:false,physicalAndroid:false,cases:[]};
const pass=(id,expected,observed)=>{report.cases.push({id,expected,observed,status:'passed'});console.log('PASS',id);};
const server=spawn(process.execPath,['dist/src/server.js'],{env:{...process.env,PORT:port},stdio:'pipe',windowsHide:true});let browser;
try{
 await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(Error('SHOP03a server timeout')),15000);server.stdout.on('data',d=>{if(String(d).includes('Balatro Advisor local')){clearTimeout(timeout);resolve();}});server.on('error',e=>{clearTimeout(timeout);reject(e);});server.on('exit',()=>{clearTimeout(timeout);reject(Error('SHOP03a server stopped'));});});
 browser=await chromium.launch({headless:true,channel:'chrome'});const pageErrors=[];
 const raw=p=>p.evaluate(k=>localStorage.getItem(k),key),record=async p=>JSON.parse(await raw(p));
 const writes=p=>p.evaluate(()=>window.__sessionWrites);
 const go=(p,screen)=>p.locator(`[data-screen="${screen}"]`).click();
 const ready=p=>p.waitForFunction(()=>document.querySelector('#ownership')?.textContent.includes('Esta pestaña tiene'));
 const load=async(p,state)=>{await go(p,'archive');await p.locator('#import-file').setInputFiles({name:'observed-shop.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(state))});await p.locator('#dialog-accept').click();await go(p,'table');await p.waitForFunction(()=>document.querySelectorAll('.bay-mini').length===150);};
 const session=async(state=fixture(),viewport={width:1440,height:1000})=>{
  const context=await browser.newContext({viewport});await context.addInitScript(k=>{
   window.__sessionWrites=0;window.__failConfirmedWrite=false;
   const original=Storage.prototype.setItem;Storage.prototype.setItem=function(name,value){if(name===k){if(window.__failConfirmedWrite)throw new DOMException('Synthetic quota failure','QuotaExceededError');window.__sessionWrites++;}return original.call(this,name,value);};
  },key);
  const p=await context.newPage();p.on('pageerror',e=>pageErrors.push(e.message));await p.goto(origin);await ready(p);await load(p,state);return {context,p};
 };
 const add=async(p,id='j_joker')=>{
  await p.locator('#bay-search').fill(id);await p.locator(`[data-bay-joker="${id}"]`).click();await p.locator('#bay-candidate').click();await p.locator('#bay-dialog').waitFor({state:'hidden'});
  const card=p.locator(`.candidate-card[data-candidate="${id}"]`).last();await card.waitFor();return card.getAttribute('data-offer-id');
 };
 const openOffer=async(p,id)=>{const card=p.locator(`.candidate-card[data-offer-id="${id}"]`);await card.locator('.candidate-hero').click();await p.locator('.candidate-dialog[open]').waitFor();return p.locator('.candidate-dialog[open]');};
 const begin=async(p,id)=>{await openOffer(p,id);await p.locator(`[data-shop-confirm="${id}"]`).click();await p.locator('#confirmation').waitFor({state:'visible'});};
 const finish=async(p,{twice=false}={})=>{await p.locator('#performed').check();if(twice)await p.locator('#dialog-accept').evaluate(b=>{b.click();b.click();});else await p.locator('#dialog-accept').click();await p.locator('#confirmation').waitFor({state:'hidden'});};
 const messages=async p=>(await p.locator('#shop-session-status,#message,#dialog-error,#bay-add-note').allTextContents()).join(' ');
 const reload=async p=>{await p.reload();await ready(p);await go(p,'table');};

 const main=await session(),{p}=main,original=await record(p),id=await add(p);
 let r=await record(p);assert.equal(r.state.observed.money.value,25);assert.equal(r.state.observed.jokers.value.length,0);assert.equal(r.state.observed.shop.value.cardOffers[0].catalogId,'joker');assert.equal(r.state.revision,original.state.revision+1);assert.equal(r.history.at(-1).kind,'correction');
 await reload(p);await p.locator(`.candidate-card[data-offer-id="${id}"]`).waitFor();assert.equal((await record(p)).state.observed.money.value,25);
 let before=await raw(p),count=await writes(p);await p.locator('#shop-recommendation').click();await p.locator('#shop-advice-dialog').waitFor({state:'visible'});await p.keyboard.press('Escape');await openOffer(p,id);await p.keyboard.press('Escape');
 await p.locator('#composition-score').click();await p.locator('#composition-details').getByRole('button',{name:'Cerrar',exact:true}).click();
 assert.equal(await raw(p),before,'Consulting advice, a joker or composition preserves exact recorded bytes');assert.equal(await writes(p),count,'Consulting causes zero storage writes');
 pass('observed-offer-and-readonly-advice','Observing a $2 Joker persists an offer without spending/acquisition; reload restores it; all consultation leaves bytes/write count unchanged',{money:25,owned:0,persistedOffer:true,consultationWrites:0});

 const observed=await record(p);await begin(p,id);await p.locator('#dialog-accept').click();assert.equal(await raw(p),before);assert.match(await p.locator('#dialog-error').innerText(),/confirm/i);await p.locator('#dialog-cancel').click();assert.equal(await raw(p),before,'Cancelled purchase does not write');
 // Keep the subsequent comparison independent from the rejected confirmation.
 if(await p.locator('.candidate-dialog[open]').count())await p.keyboard.press('Escape');await begin(p,id);await finish(p,{twice:true});
 r=await record(p);assert.equal(r.state.observed.money.value,23);assert.equal(r.state.observed.jokers.value.length,1);assert.equal(r.state.observed.jokers.value[0].catalogId,'joker');assert.equal(r.state.observed.shop.value.cardOffers.length,0);assert.equal(r.state.revision,observed.state.revision+1);assert.equal(r.history.length,observed.history.length+1);assert.equal(r.history.at(-1).action.type,'buy');assert.equal(r.history.at(-1).action.offerId,id);assert.deepEqual(r.state.observed.deck,original.state.observed.deck);assert.deepEqual(r.state.observed.handBases,original.state.observed.handBases);assert.deepEqual(r.state.observed.nextBlind,original.state.observed.nextBlind);assert.deepEqual(r.state.assumptions,original.state.assumptions);
 before=await raw(p);await reload(p);assert.equal(await raw(p),before);assert.equal(await p.locator('#money').inputValue(),'23');assert.equal(await p.locator('.inventory-panel .joker-editor').count(),1);assert.equal(await p.locator('.candidate-card').count(),0);
 pass('confirm-buy-and-reload','Explicit real purchase pays 25−2=23; one physical Joker and history entry, offer removed; double-click applies once and reload restores all',{money:23,owned:1,offers:0,actionEntries:1,noHypotheticalDataCopied:true});

 const bought=await record(p);await p.locator('#shop-undo').click();r=await record(p);assert.equal(r.state.observed.money.value,25);assert.equal(r.state.observed.jokers.value.length,0);assert.equal(r.state.observed.shop.value.cardOffers[0].offerId,id);assert.equal(r.state.revision,bought.state.revision+1);assert.equal(r.history.at(-1).kind,'undo');assert.deepEqual(r.state.observed,observed.state.observed);await reload(p);await p.locator(`.candidate-card[data-offer-id="${id}"]`).waitFor();assert.equal((await record(p)).state.observed.money.value,25);
 pass('undo-from-mesa','Undo restores observed $25/offer/inventory atomically and persists a new revision without deleting history',{money:25,owned:0,offerRestored:true,kind:'undo'});await main.context.close();

 const replace=await session(fixture({money:1,jokers:[joker('replace-owned')]})),replaceId=await add(replace.p);let d=await openOffer(replace.p,replaceId);before=await raw(replace.p);count=await writes(replace.p);await d.locator('select[aria-label^="Reemplazo para"]').selectOption('replace-owned');assert.equal(await raw(replace.p),before,'Selecting a hypothetical replacement never sells');assert.equal(await writes(replace.p),count);await replace.p.locator(`[data-shop-confirm="${replaceId}"]`).click();await finish(replace.p);r=await record(replace.p);const prior=JSON.parse(before);assert.equal(r.state.observed.money.value,0);assert.equal(r.state.observed.jokers.value.length,1);assert.notEqual(r.state.observed.jokers.value[0].instanceId,'replace-owned');assert.equal(r.state.revision,prior.state.revision+2);assert.equal(r.history.length,prior.history.length+1);assert.equal(r.history.at(-1).action.type,'replace');
 pass('replacement-is-atomic-sequence','Hypothetical choice writes nothing; confirmed sale $1 then purchase $2 pays 1+1−2=0, replaces physical ID, records one action/two revisions',{money:0,owned:1,revisionIncrement:2,historyIncrement:1});await replace.context.close();

 for(const [caseId,state,pattern] of [
  ['insufficient-money',fixture({money:1}),/insuficiente|dinero|saldo/i],
  ['no-slots',fixture({jokers:Array.from({length:5},(_,i)=>joker('full-'+i))}),/espacio|vende|hueco/i],
 ]){
  const s=await session(state),offer=await add(s.p);before=await raw(s.p);d=await openOffer(s.p,offer);const confirm=s.p.locator(`[data-shop-confirm="${offer}"]`);if(await confirm.isEnabled())await confirm.click();assert.match((await d.innerText())+' '+await messages(s.p),pattern);assert.equal(await raw(s.p),before);assert.equal(await s.p.locator('#confirmation[open]').count(),0);pass(caseId,'Illegal purchase gives a concrete reason, preserves cash/inventory/offer/history and cannot be recorded',{unchanged:true});await s.context.close();
 }

 const quota=await session(),quotaId=await add(quota.p);before=await raw(quota.p);await begin(quota.p,quotaId);await quota.p.locator('#performed').check();await quota.p.evaluate(()=>window.__failConfirmedWrite=true);await quota.p.locator('#dialog-accept').click();assert.equal(await raw(quota.p),before);assert.equal(await quota.p.locator('#money').inputValue(),'25');assert.equal(await quota.p.locator('.inventory-panel .joker-editor').count(),0);assert.equal(await quota.p.locator('.candidate-card').count(),1);assert.match(await messages(quota.p),/No se pudo guardar|almacenamiento|guardad/i);await quota.p.locator('#dialog-cancel').click();await quota.p.evaluate(()=>window.__failConfirmedWrite=false);await reload(quota.p);assert.equal(await raw(quota.p),before);
 pass('purchase-save-failure','Quota error does not deduct money, acquire the joker, remove offer or append history; prior record survives reload',{money:25,owned:0,offers:1,recordUnchanged:true});await quota.context.close();

 const edit=await session(),editId=await add(edit.p);before=await raw(edit.p);d=await openOffer(edit.p,editId);await edit.p.evaluate(()=>window.__failConfirmedWrite=true);const price=d.locator('input[id^="store-price-"]');await price.fill('3');await price.press('Tab');assert.equal(await raw(edit.p),before);assert.match(await messages(edit.p),/No se pudo guardar|almacenamiento|guardad/i);assert.equal(await edit.p.locator(`.candidate-card[data-offer-id="${editId}"] .store-joker-price`).innerText(),'$2','Failed observed-price update rolls back its visible price');await edit.p.evaluate(()=>window.__failConfirmedWrite=false);await edit.context.close();
 pass('observation-save-failure','Failed price transcription rolls back its visible value and keeps the old complete record',{price:2,recordUnchanged:true});

 const dirty=await session(),dirtyId=await add(dirty.p);before=await raw(dirty.p);await dirty.p.locator('#money').fill('26');d=await openOffer(dirty.p,dirtyId);const dirtyButton=dirty.p.locator(`[data-shop-confirm="${dirtyId}"]`);if(await dirtyButton.isEnabled())await dirtyButton.click();assert.equal(await raw(dirty.p),before);assert.match((await d.innerText())+' '+await messages(dirty.p),/guard|editad|recarga|transcri/i);assert.equal(await dirty.p.locator('#confirmation[open]').count(),0);await dirty.context.close();
 pass('dirty-draft-is-explicit','Unrecorded base-field edits block real action rather than silently merging them into a purchase',{recordUnchanged:true});

 const stale=await session(),staleId=await add(stale.p);await begin(stale.p,staleId);await stale.p.locator('#performed').check();const beforeExternal=await record(stale.p);
 const external=await stale.p.evaluate(async({binding,k})=>{const {createConfirmedStore}=await import('/dist/src/storage/confirmed-store.js');return createConfirmedStore(()=>localStorage).correct({confirmationId:'external-observed-money',confirmed:true,expected:binding,updatedAt:'2026-10-15T12:00:00Z',patch:{money:{status:'known',value:24,source:'manual'}},reason:'Synthetic external change'});},{binding:{runId:beforeExternal.state.runId,revision:beforeExternal.state.revision,rulesetId:beforeExternal.state.rulesetId},k:key});assert.equal(external.ok,true);const externalRaw=await raw(stale.p);await stale.p.locator('#dialog-accept').click();assert.equal(await raw(stale.p),externalRaw);r=await record(stale.p);assert.equal(r.state.observed.money.value,24);assert.equal(r.state.observed.jokers.value.length,0);assert.match(await messages(stale.p),/cambi|revisi|recarga|recalcula/i);await stale.context.close();
 pass('stale-confirmation','Change since opening confirmation rejects the old purchase; external $24 state/history remain intact',{money:24,owned:0,stalePurchaseApplied:false});

 const writer=await session(),writerId=await add(writer.p);before=await raw(writer.p);const second=await writer.context.newPage();second.on('pageerror',e=>pageErrors.push(e.message));await second.goto(origin);await second.waitForFunction(()=>document.querySelector('#ownership')?.textContent.includes('Modo lectura'));await second.locator(`.candidate-card[data-offer-id="${writerId}"]`).waitFor();d=await openOffer(second,writerId);const readonly=second.locator(`[data-shop-confirm="${writerId}"]`);assert.equal(await readonly.isDisabled(),true,'The actual purchase control must be disabled in the non-writer tab');assert.match(await second.locator('#ownership').textContent(),/Modo lectura/);assert.equal(await raw(second),before);assert.equal(await second.locator('#confirmation[open]').count(),0);
 pass('second-tab-readonly','A second tab can inspect the persisted shop but cannot confirm a purchase while the first owns the write lock',{recordUnchanged:true});

 await second.keyboard.press('Escape');await second.locator('.storage-status > summary').click();await second.getByRole('button',{name:'Solicitar control',exact:true}).click();await second.waitForFunction(()=>document.querySelector('#ownership')?.textContent.includes('Esperando control'));await writer.p.locator('.storage-status > summary').click();await writer.p.getByRole('button',{name:'Liberar control',exact:true}).click();await ready(second);d=await openOffer(second,writerId);assert.equal(await second.locator(`[data-shop-confirm="${writerId}"]`).isEnabled(),true,'Ownership gain must re-enable a legal purchase, without stale local-disabled state');await second.locator(`[data-shop-confirm="${writerId}"]`).click();await finish(second);r=await record(second);assert.equal(r.state.observed.money.value,23);assert.equal(r.state.observed.jokers.value.length,1);assert.equal(r.state.observed.shop.value.cardOffers.length,0);await writer.context.close();
 pass('second-tab-ownership-gain','The waiting tab obtains the lock, re-enables Compré and records exactly one $25−$2=$23 purchase',{money:23,owned:1,offers:0});

 const art=fixture();art.observed.shop.value.cardOffers=[{offerId:'legacy-art-offer',catalogId:'j_joker',label:'Imported Joker art ID',kind:'joker',price:known(2),edition:known('base'),stickers:known([])}];const imported=await session(art);await imported.p.locator('.candidate-card[data-candidate="j_joker"][data-offer-id="legacy-art-offer"]').waitFor();d=await openOffer(imported.p,'legacy-art-offer');const importedBefore=await record(imported.p);await d.locator('input[id^="store-price-"]').fill('3');await d.locator('input[id^="store-price-"]').press('Tab');r=await record(imported.p);assert.equal(r.state.observed.shop.value.cardOffers.length,1,'Mapping the imported art ID must update, never append a duplicate offer');assert.equal(r.state.observed.shop.value.cardOffers[0].offerId,'legacy-art-offer');assert.equal(r.state.observed.shop.value.cardOffers[0].catalogId,'joker');assert.equal(r.state.observed.shop.value.cardOffers[0].price.value,3);assert.equal(r.state.observed.money.value,25);assert.equal(r.state.observed.jokers.value.length,0);assert.equal(r.state.revision,importedBefore.state.revision+1);assert.equal(r.history.at(-1).kind,'correction');await imported.p.keyboard.press('Escape');await reload(imported.p);await imported.p.locator('.candidate-card[data-offer-id="legacy-art-offer"]').waitFor();assert.equal(await imported.p.locator('.candidate-card').count(),1);assert.equal((await record(imported.p)).state.observed.shop.value.cardOffers[0].price.value,3);await imported.context.close();
 pass('imported-art-id-edit','Imported j_joker renders as Joker; price 2→3 normalizes its catalog ID and persists one offer with the same ID, without acquisition or duplication',{catalogId:'joker',offerId:'legacy-art-offer',offers:1,price:3,money:25});

 const mobile=await session(fixture(),{width:390,height:844}),mobileId=await add(mobile.p);for(const width of [360,390]){await mobile.p.setViewportSize({width,height:844});await openOffer(mobile.p,mobileId);assert.equal(await mobile.p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);const box=await mobile.p.locator(`[data-shop-confirm="${mobileId}"]`).boundingBox();assert.ok(box&&box.x>=0&&box.x+box.width<=width);await mobile.p.keyboard.press('Escape');}await begin(mobile.p,mobileId);await finish(mobile.p);assert.equal((await record(mobile.p)).state.observed.money.value,23);await mobile.p.screenshot({path:dir+'/mobile-confirmed.png',fullPage:true});await mobile.context.close();
 pass('mobile-confirmation','Observed offer and explicit confirmation work at 360/390px without document overflow',{money:23,widths:[360,390],physicalAndroid:false});

 assert.deepEqual(pageErrors,[]);report.status='passed';report.pageErrors=pageErrors;await writeFile(dir+'/report.json',JSON.stringify(report,null,2)+'\n');console.log('PASS SHOP03a',report.cases.length,'groups');
}catch(error){report.status='failed';report.error=error.stack||error.message;await writeFile(dir+'/report.json',JSON.stringify(report,null,2)+'\n');throw error;}
finally{await browser?.close();server.kill();}
